        byte[] bytes = outputStream.toByteArray();
        EmptyMessage newMessage = EMPTY_MESSAGE_SCHEMA.newMessage();
        ProtostuffIOUtil.mergeFrom(bytes, newMessage, EMPTY_MESSAGE_SCHEMA);
        Assert.assertEquals(0, bytes.length);
